4	/**
5	 * Public read access to establishments. Every public API/page goes through here so the
6	 * visibility rules live in ONE place:
7	 *   - status 'verified' always visible; 'pending_verification' only if setting public_show_unverified=1 (labelled);
8	 *   - 'needs_review' and 'inactive' are never public;
9	 *   - coordinates are plotted only if present AND (coords_verified=1 OR setting plot_unverified_coords=1);
10	 *   - the emergency flag is exposed only when emergency_verified_at is set;
11	 *   - only is_public contacts are returned.
12	 */
13	
14	function repo_public_status_list(): array
15	{
16	    return setting('public_show_unverified', '1') === '1'
17	        ? ['verified', 'pending_verification']
18	        : ['verified'];
19	}
20	
21	function repo_plot_requires_verified(): bool
22	{
23	    return setting('plot_unverified_coords', '0') !== '1';
24	}
25	
26	function like_escape(string $s): string
27	{
28	    return str_replace(['\\', '%', '_'], ['\\\\', '\\%', '\\_'], $s);
29	}
