31	/** Build WHERE + params for public listing filters. */
32	function repo_build_where(array $f, array &$params): string
33	{
34	    $statuses = repo_public_status_list();
35	    $ph = implode(',', array_fill(0, count($statuses), '?'));
36	    $where = ["e.status IN ($ph)"];
37	    foreach ($statuses as $s) {
38	        $params[] = $s;
39	    }
40	    $where[] = 'b.is_active = 1';
41	
42	    if (!empty($f['barangay_id'])) {
43	        $where[] = 'e.barangay_id = ?';
44	        $params[] = (int)$f['barangay_id'];
45	    }
46	    if (!empty($f['category_id'])) {
47	        $where[] = '(e.primary_category_id = ? OR EXISTS (SELECT 1 FROM establishment_categories ec WHERE ec.establishment_id = e.establishment_id AND ec.category_id = ?))';
48	        $params[] = (int)$f['category_id'];
49	        $params[] = (int)$f['category_id'];
50	    }
51	    if (!empty($f['classification']) && in_array($f['classification'], ['public', 'private'], true)) {
52	        $where[] = 'e.classification = ?';
53	        $params[] = $f['classification'];
54	    }
55	    if (!empty($f['zone'])) {
56	        $where[] = 'e.zone = ?';
57	        $params[] = (string)$f['zone'];
58	    }
59	    if (!empty($f['essential'])) {
60	        $where[] = 'c.is_essential = 1';
61	    }
62	    if (!empty($f['emergency'])) {
63	        $where[] = 'EXISTS (SELECT 1 FROM facilities fx WHERE fx.establishment_id = e.establishment_id AND fx.is_emergency = 1 AND fx.emergency_verified_at IS NOT NULL)';
64	    }
65	    if (!empty($f['q'])) {
66	        $like = '%' . like_escape((string)$f['q']) . '%';
67	        $where[] = '(e.name LIKE ? OR e.description LIKE ? OR e.street_address LIKE ? OR e.landmark LIKE ? OR e.zone LIKE ? OR c.name_en LIKE ? OR c.name_tl LIKE ?)';
68	        for ($i = 0; $i < 7; $i++) {
69	            $params[] = $like;
70	        }
71	    }
72	    return implode(' AND ', $where);
73	}
