89	/** Shape a DB row into the public JSON structure, enforcing the visibility rules. */
90	function repo_shape(array $r): array
91	{
92	    $hasCoords = $r['latitude'] !== null && $r['longitude'] !== null;
93	    $plottable = $hasCoords && ((int)$r['coords_verified'] === 1 || !repo_plot_requires_verified());
94	    $emergency = (int)($r['f_is_emergency'] ?? 0) === 1 && !empty($r['f_emergency_verified_at']);
95	
96	    return [
97	        'id'              => (int)$r['establishment_id'],
98	        'name'            => $r['name'],
99	        'description'     => $r['description'],
100	        'barangay_id'     => (int)$r['barangay_id'],
101	        'barangay'        => $r['barangay_name'],
102	        'category'        => [
103	            'id'    => (int)$r['primary_category_id'],
104	            'slug'  => $r['category_slug'],
105	            'name'  => cat_name(['name_en' => $r['category_name_en'], 'name_tl' => $r['category_name_tl']]),
106	            'icon'  => $r['category_icon'],
107	            'color' => $r['category_color'],
108	            'essential' => (int)$r['category_is_essential'] === 1,
109	        ],
110	        'address'         => $r['street_address'],
111	        'landmark'        => $r['landmark'],
112	        'directions'      => $r['directions_text'],
113	        'zone'            => $r['zone'],
114	        'classification'  => $r['classification'],
115	        'status'          => $r['status'],
116	        'verified'        => $r['status'] === 'verified',
117	        'last_verified_at'=> $r['last_verified_at'],
118	        'hours_note'      => $r['hours_note'],
119	        'photo_url'       => $r['photo_path'] ? url('uploads/' . rawurlencode(basename((string)$r['photo_path']))) : null,
120	        'is_sample'       => (int)$r['is_sample'] === 1,
121	        'osm_sourced'     => !empty($r['osm_ref']),
122	        'has_coordinates' => $hasCoords,
123	        'plottable'       => $plottable,
124	        'coords_verified' => (int)$r['coords_verified'] === 1,
125	        // Coordinates are only sent when the point may be plotted; otherwise the record is list-only.
126	        'lat'             => $plottable ? (float)$r['latitude'] : null,
127	        'lng'             => $plottable ? (float)$r['longitude'] : null,
128	        'emergency'       => $emergency,
129	        'facility_type'   => $r['f_type'] ?? null,
130	        'services'        => $r['f_services'] ?? null,
131	    ];
132	}
133	
134	function repo_search(array $f, int $limit = 50, int $offset = 0): array
135	{
136	    $params = [];
137	    $where = repo_build_where($f, $params);
138	    $limit = max(1, min(200, $limit));
139	    $offset = max(0, $offset);
140	
141	    $cnt = db()->prepare("SELECT COUNT(*) " . REPO_FROM . " WHERE $where");
142	    $cnt->execute($params);
143	    $total = (int)$cnt->fetchColumn();
144	
145	    $sql = "SELECT " . REPO_SELECT . " " . REPO_FROM . " WHERE $where ORDER BY e.name ASC LIMIT $limit OFFSET $offset";
146	    $st = db()->prepare($sql);
147	    $st->execute($params);
148	    return ['total' => $total, 'items' => array_map('repo_shape', $st->fetchAll())];
149	}
150	
151	function repo_find(int $id): ?array
152	{
153	    $params = [];
154	    $where = repo_build_where([], $params) . ' AND e.establishment_id = ?';
155	    $params[] = $id;
156	    $st = db()->prepare("SELECT " . REPO_SELECT . " " . REPO_FROM . " WHERE $where");
157	    $st->execute($params);
158	    $r = $st->fetch();
159	    if (!$r) {
160	        return null;
161	    }
162	    $o = repo_shape($r);
163	
164	    $c = db()->prepare('SELECT contact_type, contact_value FROM establishment_contacts WHERE establishment_id = ? AND is_public = 1 ORDER BY contact_id');
165	    $c->execute([$id]);
166	    $o['contacts'] = $c->fetchAll();
167	
168	    $h = db()->prepare('SELECT day_of_week, opens_at, closes_at, is_closed, is_24h FROM operating_hours WHERE establishment_id = ? ORDER BY day_of_week');
169	    $h->execute([$id]);
170	    $o['hours'] = array_map(static function ($x) {
171	        return [
172	            'day'    => (int)$x['day_of_week'],
173	            'opens'  => $x['opens_at'] ? substr($x['opens_at'], 0, 5) : null,
174	            'closes' => $x['closes_at'] ? substr($x['closes_at'], 0, 5) : null,
175	            'closed' => (int)$x['is_closed'] === 1,
176	            'is_24h' => (int)$x['is_24h'] === 1,
177	        ];
178	    }, $h->fetchAll());
179	    return $o;
180	}
181	
182	/** Markers: only plottable records, minimal fields. */
183	function repo_markers(array $f, int $limit = 1000): array
184	{
185	    $params = [];
186	    $where = repo_build_where($f, $params) . ' AND e.latitude IS NOT NULL AND e.longitude IS NOT NULL';
187	    if (repo_plot_requires_verified()) {
188	        $where .= ' AND e.coords_verified = 1';
189	    }
190	    $limit = max(1, min(2000, $limit));
191	    $st = db()->prepare("SELECT " . REPO_SELECT . " " . REPO_FROM . " WHERE $where ORDER BY e.name LIMIT $limit");
192	    $st->execute($params);
193	    $out = [];
194	    foreach ($st->fetchAll() as $r) {
195	        $s = repo_shape($r);
196	        $out[] = [
197	            'id' => $s['id'], 'name' => $s['name'], 'lat' => $s['lat'], 'lng' => $s['lng'],
198	            'category' => $s['category'], 'address' => $s['address'], 'verified' => $s['verified'],
199	            'emergency' => $s['emergency'], 'is_sample' => $s['is_sample'],
200	        ];
201	    }
202	    return $out;
203	}
