244	    $rows = db()->query($sql)->fetchAll();
245	    return array_map(static function ($r) {
246	        return [
247	            'id' => (int)$r['category_id'], 'slug' => $r['slug'], 'name' => cat_name($r),
248	            'name_en' => $r['name_en'], 'name_tl' => $r['name_tl'],
249	            'icon' => $r['icon'], 'color' => $r['color'], 'essential' => (int)$r['is_essential'] === 1,
250	        ];
251	    }, $rows);
252	}
