265	            'boundary' => ($r['boundary_geojson'] && $r['boundary_source']) ? json_decode($r['boundary_geojson'], true) : null,
266	            'boundary_source' => $r['boundary_source'],
267	            'boundary_verified' => (int)$r['boundary_verified'] === 1,
268	            'hall_address' => $r['hall_address'], 'hall_phone' => $r['hall_phone'],
269	            'is_sample' => (int)$r['is_sample'] === 1,
270	        ];
271	    }, $rows);
